// Validates the webhook payload and stakes out a per-run work directory.
// Everything downstream reads its paths from here, so a run never collides
// with a concurrent one.
const fs = require('fs');
const ROOT = '/data/workflow';

// TikTok / Shorts / Reels want 9:16. Landscape stays the default because it is
// what you actually watch while practising at a desk.
const FORMATS = {
  landscape: { key: 'landscape', width: 1280, height: 720 },
  portrait: { key: 'portrait', width: 1080, height: 1920 },
};

const raw = $input.first().json;
const body = raw.body ?? raw ?? {};

const topic = String(body.topic ?? '').trim();
if (!topic) {
  throw new Error('`topic` is required — POST e.g. {"topic":"ordering coffee"}');
}
if (topic.length > 120) {
  throw new Error('`topic` must be 120 characters or fewer');
}

const clamp = (value, lo, hi, fallback) => {
  const n = Number(value);
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : fallback;
};

const orientation = String(body.orientation ?? 'landscape').toLowerCase();
if (!['landscape', 'portrait', 'both'].includes(orientation)) {
  throw new Error(`\`orientation\` must be landscape, portrait or both — got "${orientation}"`);
}
const formats = orientation === 'both'
  ? [FORMATS.landscape, FORMATS.portrait]
  : [FORMATS[orientation]];

const stamp = new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 14);
const runId = `${stamp}_${Math.random().toString(36).slice(2, 8)}`;
const workDir = `${ROOT}/work/${runId}`;
fs.mkdirSync(workDir, { recursive: true });

// Background music. `music` accepts three shapes so the common cases stay short:
//   omitted / true  -> use assets/music/ if anything is in there, else look for a
//                      CC0 bed on Openverse
//   false / "off"   -> speech only, exactly as before this existed
//   "<name or path>" -> that file; a bare name resolves inside assets/music/
// Everything is optional by design: no bed found is a normal run, not a failure.
const musicRaw = body.music;
const musicWord = typeof musicRaw === 'string' ? musicRaw.trim().toLowerCase() : '';
const musicEnabled = !(musicRaw === false || musicWord === 'off' || musicWord === 'false');
const musicFile = typeof musicRaw === 'string' && !['', 'on', 'off', 'auto', 'true', 'false'].includes(musicWord)
  ? musicRaw.trim()
  : '';

// The dialogue is a two-person exchange, so it gets two voices. `voice` is kept
// as a legacy escape hatch: pass it and both speakers use that single voice.
const singleVoice = body.voice ? String(body.voice) : '';

// The first format keeps the plain <runId>.mp4 name so existing callers and the
// spec's /data/workflow/output/ contract still hold; extras get a suffix.
const outputs = formats.map((f, i) => ({
  ...f,
  path: `${ROOT}/output/${runId}${i === 0 ? '' : `_${f.key}`}.mp4`,
}));

return [{
  json: {
    runId,
    workDir,
    manifestPath: `${workDir}/manifest.json`,
    srtPath: `${workDir}/subtitle.srt`,
    planPath: `${workDir}/plan.json`,
    pexelsPath: `${workDir}/pexels.json`,
    musicPath: `${workDir}/music.json`,
    outputPath: outputs[0].path,
    outputs,
    outputDir: `${ROOT}/output`,
    topic,
    sentenceCount: Math.round(clamp(body.sentenceCount, 5, 8, 6)),
    gapSeconds: clamp(body.gapSeconds, 1, 10, 2.5),
    voiceA: singleVoice || String(body.voiceA ?? 'en-US-AvaNeural'),
    voiceB: singleVoice || String(body.voiceB ?? 'en-US-AndrewNeural'),
    speed: clamp(body.speed, 0.5, 1.5, 0.9),
    background: String(body.background ?? ''),
    orientation,
    // Target loudness. -14 LUFS is what TikTok/YouTube normalise to, so hitting it
    // means the platform leaves the audio alone.
    targetLufs: clamp(body.targetLufs, -30, -8, -14),
    music: {
      enabled: musicEnabled,
      file: musicFile,
      query: String(body.musicQuery ?? '').trim().slice(0, 80),
      // How far the bed sits under the speech, in LUFS. -24 is background you can
      // actually hear: present through the shadowing gaps without competing with
      // the line being repeated. Started at -30, which measured correct but played
      // as near-silence on a phone speaker.
      db: clamp(body.musicDb, -60, -6, -24),
    },
    // The TikTok cover. Off by request only - it costs one extra frame decode.
    thumbnail: body.thumbnail !== false,
    // Where to freeze. Left null, build_video.js picks a point inside the first
    // scene that no transition is passing through.
    thumbnailTime: Number.isFinite(Number(body.thumbnailTime))
      ? clamp(body.thumbnailTime, 0, 3600, 0)
      : null,
    keepWorkDir: body.keepWorkDir === true,
  },
}];

// STUB: stands in for the Groq call so the rest of the pipeline can be
// proven without spending free-tier quota. Edited via host/workflows/shadowing-stub.js.
return [{ json: { choices: [{ message: { content: "{\"sentences\":[{\"speaker\":\"A\",\"en\":\"Hi there, could I get a large iced latte, please?\",\"vi\":\"Chào bạn, cho tôi một ly latte đá lớn nhé?\",\"imageQuery\":\"iced latte cup\"},{\"speaker\":\"B\",\"en\":\"Sure thing. Would you like any syrup with that?\",\"vi\":\"Được thôi. Bạn có muốn thêm siro không?\",\"imageQuery\":\"coffee syrup bottles\"},{\"speaker\":\"A\",\"en\":\"Just a little vanilla, and can you make it less sweet?\",\"vi\":\"Một chút vani thôi, và làm ít ngọt giúp tôi được không?\",\"imageQuery\":\"vanilla beans\"},{\"speaker\":\"B\",\"en\":\"No problem. That comes to $5.75 altogether.\",\"vi\":\"Không vấn đề gì. Tổng cộng là 5,75 đô la.\",\"imageQuery\":\"cafe cash register\"},{\"speaker\":\"A\",\"en\":\"Here you go. Do you take cards, or is it cash only?\",\"vi\":\"Của bạn đây. Bạn nhận thẻ hay chỉ tiền mặt?\",\"imageQuery\":\"credit card payment terminal\"},{\"speaker\":\"B\",\"en\":\"Cards are fine. Your drink will be ready in 3 minutes.\",\"vi\":\"Thẻ cũng được. Đồ uống của bạn sẽ xong sau 3 phút.\",\"imageQuery\":\"barista espresso machine\"}]}" } }] } }];

// Turns the Groq completion into one item per sentence, and writes the manifest
// the media scripts read.
//
// Two texts are kept per sentence on purpose:
//   `en`       - verbatim, this is what gets burned into the subtitle
//   `ttsText`  - normalised, this is what edge-tts is asked to say
// Neural TTS mangles digits, symbols and emoji ("$3.50" becomes "dollar three
// point five zero"), so numerals are spelled out and anything unspeakable is
// dropped before synthesis - without disturbing what the learner reads.
const fs = require('fs');
const cfg = $('Prepare Run').first().json;

// ---------- number spelling ----------------------------------------------
const ONES = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
  'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen',
  'eighteen', 'nineteen'];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];

function spellInt(n) {
  if (n < 0) return `minus ${spellInt(-n)}`;
  if (n < 20) return ONES[n];
  if (n < 100) return TENS[Math.floor(n / 10)] + (n % 10 ? `-${ONES[n % 10]}` : '');
  if (n < 1000) {
    return `${ONES[Math.floor(n / 100)]} hundred` + (n % 100 ? ` and ${spellInt(n % 100)}` : '');
  }
  if (n < 1000000) {
    return `${spellInt(Math.floor(n / 1000))} thousand` + (n % 1000 ? ` ${spellInt(n % 1000)}` : '');
  }
  return String(n); // beyond small talk; leave it alone rather than mangle it
}

function normalizeForTts(input) {
  let t = String(input).normalize('NFC');

  // Typographic characters the voice reads as literal noise.
  t = t.replace(/[‘’‛]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, ', ')
    .replace(/…/g, '.');

  // Emoji, pictographs, variation selectors and zero-width joiners.
  t = t.replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE00}-\u{FE0F}\u{200B}-\u{200D}]/gu, '');

  // Markdown emphasis leaking out of the model.
  t = t.replace(/[*_`#>]/g, '');

  // Money first: "$3.50" -> "three dollars fifty cents".
  t = t.replace(/\$\s?(\d+)(?:\.(\d{2}))?/g, (_, d, c) => {
    const dollars = `${spellInt(Number(d))} ${Number(d) === 1 ? 'dollar' : 'dollars'}`;
    return c && Number(c) ? `${dollars} ${spellInt(Number(c))} cents` : dollars;
  });

  // Clock times: "3:30" -> "three thirty", "7:00" -> "seven o'clock".
  t = t.replace(/\b(\d{1,2}):(\d{2})\b/g, (_, h, m) => (Number(m) === 0
    ? `${spellInt(Number(h))} o'clock`
    : `${spellInt(Number(h))} ${spellInt(Number(m))}`));

  // "3pm" -> "three p m" (spaced so the voice says the letters).
  t = t.replace(/\b(\d{1,2})\s?(am|pm)\b/gi,
    (_, h, s) => `${spellInt(Number(h))} ${s.toLowerCase().split('').join(' ')}`);

  // Percentages, then any bare integer left over.
  t = t.replace(/\b(\d+)\s?%/g, (_, d) => `${spellInt(Number(d))} percent`);
  t = t.replace(/\b\d+\b/g, (m) => spellInt(Number(m)));

  // Anything remaining that is not speech or punctuation the voice honours.
  t = t.replace(/[^A-Za-z0-9 '.,!?;:-]/g, ' ');

  return t.replace(/\s+/g, ' ').replace(/\s+([.,!?;:])/g, '$1').trim();
}

// ---------- pull the payload out of the completion ------------------------
const completion = $input.first().json;
const content = completion?.choices?.[0]?.message?.content;
if (!content) {
  throw new Error(`Groq returned no content: ${JSON.stringify(completion).slice(0, 400)}`);
}

let parsed;
try {
  parsed = JSON.parse(content);
} catch (err) {
  // json_object mode is usually clean, but a fenced block still shows up sometimes.
  const match = content.match(/\{[\s\S]*\}/);
  if (!match) throw new Error(`Groq content is not JSON: ${content.slice(0, 300)}`);
  parsed = JSON.parse(match[0]);
}

const rows = Array.isArray(parsed.sentences) ? parsed.sentences : [];
if (rows.length < 5) {
  throw new Error(`expected at least 5 sentences, got ${rows.length}`);
}

// Two speakers get two voices. The model is asked to alternate A/B, but a model
// that forgets the field would silently collapse the dialogue back to one voice,
// so an absent or unexpected value falls back to alternating by position.
const VOICES = { A: cfg.voiceA, B: cfg.voiceB };

const sentences = rows.slice(0, cfg.sentenceCount).map((row, i) => {
  const en = String(row.en ?? row.english ?? '').trim();
  const vi = String(row.vi ?? row.vietnamese ?? '').trim();
  if (!en) throw new Error(`sentence ${i + 1} has no English text`);

  const declared = String(row.speaker ?? '').trim().toUpperCase();
  const speaker = VOICES[declared] ? declared : (i % 2 === 0 ? 'A' : 'B');

  // Falls back to the topic so a sentence without a usable query still gets a
  // scene rather than a hole in the video.
  const imageQuery = String(row.imageQuery ?? '').trim().slice(0, 80) || cfg.topic;

  return { idx: i + 1, speaker, en, vi, imageQuery, ttsText: normalizeForTts(en) };
});

// The manifest is the contract the container/cli/* scripts read: they take a
// directory on argv and nothing else, so anything they need has to be in here.
// fetch_music.js reads `music` the way fetch_scenes.js reads `sentences`.
fs.writeFileSync(
  cfg.manifestPath,
  JSON.stringify({ runId: cfg.runId, topic: cfg.topic, music: cfg.music, sentences }, null, 2),
  'utf8',
);

return sentences.map((s) => ({ json: { ...s, voice: VOICES[s.speaker], speed: cfg.speed } }));

