// Collects whatever the Pexels search returned into pexels.json, which
// fetch_scenes.js then reads.
//
// The indirection exists so the Pexels key stays in the n8n credential store:
// the HTTP node holds the credential, this node only ever sees the URLs it
// returned, and the CLI script never touches a key at all.
//
// Pexels is entirely optional. With no key, a bad key, or an exhausted quota the
// search node passes its error through instead of failing, this node writes an
// empty map, and every scene falls back to Openverse.
const fs = require('fs');
const cfg = $('Prepare Run').first().json;

const byIdx = {};
let searched = 0;
let failed = 0;

for (let i = 0; i < $input.all().length; i += 1) {
  const item = $input.all()[i];

  let idx;
  try {
    idx = $('Parse & Normalize').all()[i]?.json?.idx;
  } catch {
    idx = undefined;
  }
  if (!idx) continue;

  if (item.json?.error) {
    failed += 1;
    continue;
  }

  searched += 1;
  // large2x is ~1880px wide: plenty for a 1920 frame, far smaller than original.
  const photo = (item.json?.photos ?? [])[0];
  const url = photo?.src?.large2x ?? photo?.src?.large ?? null;
  if (url) byIdx[idx] = url;
}

fs.writeFileSync(cfg.pexelsPath, JSON.stringify(byIdx), 'utf8');

if (failed) {
  console.log(`[shadowing] run ${cfg.runId}: ${failed} Pexels lookup(s) failed, those scenes fall back to Openverse`);
}

return [{
  json: {
    pexelsPath: cfg.pexelsPath,
    pexelsHits: Object.keys(byIdx).length,
    pexelsSearched: searched,
    pexelsFailed: failed,
  },
}];

// Lays the probed sentences on a timeline and writes both the .srt and the
// ffmpeg plan. This node and build_video.js must agree on the arithmetic, so
// the single rule is: sentence i starts at the sum of every earlier
// (duration + gap). build_video.js realises exactly that with apad+concat.
//
// Timing comes from the PCM durations probe_durations.js measured, not from the
// mp3 headers - see the comment there for why that matters.
const fs = require('fs');
const cfg = $('Prepare Run').first().json;

const probeRaw = $input.first().json.stdout;
if (!probeRaw) {
  throw new Error(`duration probe produced no output: ${JSON.stringify($input.first().json).slice(0, 300)}`);
}
const probe = JSON.parse(probeRaw);

const segments = (probe.segments ?? []).sort((a, b) => a.idx - b.idx);
const skipped = probe.missing ?? [];
if (!segments.length) {
  throw new Error('every sentence failed TTS - nothing to build a video from');
}

const gap = cfg.gapSeconds;
const CUE_GUARD = 0.08; // keeps consecutive cues from touching

/** seconds -> SRT timestamp (HH:MM:SS,mmm) */
function srtTime(sec) {
  const total = Math.max(0, Math.round(sec * 1000));
  const pad = (n, w = 2) => String(n).padStart(w, '0');
  return [
    pad(Math.floor(total / 3600000)),
    pad(Math.floor((total % 3600000) / 60000)),
    pad(Math.floor((total % 60000) / 1000)),
  ].join(':') + ',' + pad(total % 1000, 3);
}

let cursor = 0;
const cues = segments.map((seg, i) => {
  const start = cursor;
  // The cue deliberately stays up through the silence: the learner is repeating
  // the line during that gap and still needs to read it.
  const end = start + seg.duration + gap - CUE_GUARD;
  cursor = start + seg.duration + gap;
  return { index: i + 1, idx: seg.idx, start, end, en: seg.en, vi: seg.vi };
});

const srt = cues
  .map((c) => `${c.index}\n${srtTime(c.start)} --> ${srtTime(c.end)}\n${c.en}${c.vi ? `\n${c.vi}` : ''}\n`)
  .join('\n');

fs.writeFileSync(cfg.srtPath, srt, 'utf8');

// Scenes are optional: the Fetch Scenes node exits 0 with an empty list when no
// image could be found, and build_video.js falls back to the flat background.
let scenes = [];
let scenesMissing = [];
try {
  const raw = $('Fetch Scenes').first().json.stdout;
  if (raw) {
    const parsed = JSON.parse(raw);
    scenes = parsed.scenes ?? [];
    scenesMissing = parsed.missing ?? [];
  }
} catch (err) {
  console.log(`[shadowing] run ${cfg.runId}: no scenes (${err.message})`);
}

// Music is optional in exactly the same way scenes are: the fetcher exits 0 with
// `music: null` when it found nothing, and build_video.js ships speech only.
let music = null;
let musicReason = null;
try {
  const raw = $('Fetch Music').first().json.stdout;
  if (raw) {
    const parsed = JSON.parse(raw);
    music = parsed.music ?? null;
    musicReason = parsed.reason ?? null;
  }
} catch (err) {
  musicReason = err.message;
  console.log(`[shadowing] run ${cfg.runId}: no music (${err.message})`);
}

const plan = {
  runId: cfg.runId,
  topic: cfg.topic,
  workDir: cfg.workDir,
  srtPath: cfg.srtPath,
  outputs: cfg.outputs,
  gapSeconds: gap,
  scenes: scenes.map((sc) => ({ idx: sc.idx, file: sc.file })),
  // `db` travels with the file so build_video.js needs no second source of config.
  music: music ? { ...music, db: cfg.music.db } : null,
  thumbnail: cfg.thumbnail,
  thumbnailTime: cfg.thumbnailTime,
  targetLufs: cfg.targetLufs,
  background: cfg.background,
  segments: segments.map((s) => ({ idx: s.idx, wav: s.wav, duration: s.duration })),
};
fs.writeFileSync(cfg.planPath, JSON.stringify(plan, null, 2), 'utf8');

if (skipped.length) {
  console.log(`[shadowing] run ${cfg.runId}: skipped ${skipped.length} sentence(s):`,
    JSON.stringify(skipped));
}

return [{
  json: {
    planPath: cfg.planPath,
    srtPath: cfg.srtPath,
    cueCount: cues.length,
    skipped,
    scenes,
    scenesMissing,
    music,
    musicReason,
    expectedDurationSec: Math.round(cursor * 100) / 100,
  },
}];

// Shapes the webhook response and clears the run's scratch space.
//
// Skipped sentences are surfaced rather than swallowed: the video is still valid,
// but the caller should know it is short a line and why.
const fs = require('fs');
const cfg = $('Prepare Run').first().json;
const srt = $('Build SRT').first().json;

const raw = $input.first().json.stdout;
if (!raw) {
  throw new Error(`video assembly produced no output: ${JSON.stringify($input.first().json).slice(0, 300)}`);
}
const built = JSON.parse(raw);

// Everything worth keeping moves next to the mp4, so output/ holds the complete
// deliverable and work/ is pure scratch that can be wiped without thought.
// A run of eight sentences leaves ~4 MB of mp3 and wav behind otherwise.
//
// The record is composed rather than copied: it folds the manifest together with
// the measured durations and gap windows, which is what host/verify-sync.js needs
// to re-audit subtitle drift once the work directory is gone.
const keptSrt = `${cfg.outputDir}/${cfg.runId}.srt`;
const keptRecord = `${cfg.outputDir}/${cfg.runId}.json`;
let cleaned = false;

try {
  const manifest = JSON.parse(fs.readFileSync(cfg.manifestPath, 'utf8'));
  const plan = JSON.parse(fs.readFileSync(cfg.planPath, 'utf8'));

  fs.copyFileSync(cfg.srtPath, keptSrt);
  fs.writeFileSync(keptRecord, JSON.stringify({
    runId: cfg.runId,
    topic: cfg.topic,
    createdAt: new Date().toISOString(),
    gapSeconds: cfg.gapSeconds,
    voices: { A: cfg.voiceA, B: cfg.voiceB },
    speed: cfg.speed,
    orientation: cfg.orientation,
    sentences: manifest.sentences,
    segments: plan.segments.map((s) => ({ idx: s.idx, duration: s.duration })),
    scenes: srt.scenes,
    outputs: built.outputs,
    covers: built.covers ?? [],
    durationSec: built.durationSec,
    // host/verify-sync.js reads `audio` to prove the music bed did not move the
    // timeline the subtitles were built from.
    audio: built.audio ?? null,
    music: built.music ?? null,
    loudness: built.loudness,
    skippedSentences: srt.skipped,
  }, null, 2), 'utf8');

  if (!cfg.keepWorkDir) {
    fs.rmSync(cfg.workDir, { recursive: true, force: true });
    cleaned = true;
  }
} catch (err) {
  // Housekeeping must never fail a run that already produced a video.
  console.log(`[shadowing] run ${cfg.runId}: cleanup skipped - ${err.message}`);
}

return [{
  json: {
    ok: true,
    runId: cfg.runId,
    topic: cfg.topic,
    video: built.output,
    videos: built.outputs,
    cover: built.cover ?? null,
    covers: built.covers ?? [],
    subtitle: keptSrt,
    record: keptRecord,
    sentences: built.segments,
    gapSeconds: cfg.gapSeconds,
    voices: { A: cfg.voiceA, B: cfg.voiceB },
    orientation: cfg.orientation,
    durationSec: built.durationSec,
    sizeBytes: built.sizeBytes,
    audio: built.audio ?? null,
    loudness: built.loudness,
    // `music: null` means none was asked for or none was found; `used: false`
    // means one was found and then rejected - the reason says which.
    music: built.music
      ? { ...built.music, lookup: srt.musicReason ?? null }
      : { used: false, reason: srt.musicReason ?? 'no music' },
    skippedSentences: srt.skipped,
    scenes: {
      used: (srt.scenes ?? []).length,
      missing: srt.scenesMissing ?? [],
      // Only CC BY images oblige a credit line; cc0 and Pexels do not.
      attributions: (srt.scenes ?? []).map((sc) => sc.attribution).filter(Boolean),
    },
    coverError: built.coverError ?? null,
    workDirCleaned: cleaned,
  },
}];
